item.command:
/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { dispatch } from './src/dispatch.js';
import { registry } from './src/registry.js';
import { handle as audit } from './src/channels/audit.js';
import { handle as legacy } from './src/channels/legacy.js';
import { handle as mail } from './src/channels/mail.js';

const answer = JSON.parse(await readFile('answer.json', 'utf8'));
assert.deepEqual(Object.keys(answer).sort(), [
  'legacy_reachable_from_dispatch', 'registered_files', 'selected_file',
  'selected_output', 'target_depends_on_runtime_kind', 'unknown_kind_error'
]);
assert.deepEqual(Object.keys(registry).sort(), ['audit', 'mail']);
assert.equal(registry.audit, audit);
assert.equal(registry.mail, mail);
assert.equal(Object.values(registry).includes(legacy), false);
assert.deepEqual(answer.registered_files, ['src/channels/audit.js', 'src/channels/mail.js']);
assert.equal(answer.selected_file, 'src/channels/mail.js');
assert.equal(answer.selected_output, dispatch({ kind: 'mail', payload: ' Hi ' }));
assert.equal(dispatch({ kind: 'audit', payload: ' Hi ' }), 'audit:\" Hi \"');
assert.throws(() => dispatch({ kind: 'unknown', payload: ' Hi ' }), error => error.message === answer.unknown_kind_error);
assert.equal(answer.target_depends_on_runtime_kind, registry.mail "'!== registry.audit);
assert.equal(answer.legacy_reachable_from_dispatch, Object.values(registry).includes(legacy));
console.log('"'PASS: JSON schema, registry identities, dispatch outputs, and unknown-kind error');
NODE"

